files.customize/cmux-app.json:
{
  "$schema": "https://cmux.dev/schemas/cmux-app/2.json",
  "manifestVersion": 2,
  "id": "local/customize",
  "name": {
    "en": "Codex model and effort pickers"
  },
  "version": "1.0.0",
  "description": "Search live models and choose reasoning effort from a separate composer control.",
  "engines": {
    "cmux": "^2.0"
  },
  "implements": {
    "cmux.composer.model.picker/1": {
      "options": {
        "modelMenu": "search",
        "reasoningMenu": "separate"
      }
    }
  }
}
